add_filter( 'woocommerce_add_cart_item_data', 'perfectpixel_split_lines_unique_key', 10, 2 );
add_action( 'woocommerce_add_to_cart', 'perfectpixel_split_lines_add', 10, 6 );

function perfectpixel_split_lines_applies( $product_id ) {
	$ids = wp_parse_id_list( '{{split_lines_product_ids}}' );
	return ! $ids || in_array( (int) $product_id, $ids, true );
}

// A unique key makes WooCommerce create a new line instead of increasing an existing one.
function perfectpixel_split_lines_unique_key( $data, $product_id ) {
	if ( perfectpixel_split_lines_applies( $product_id ) ) {
		$data['perfectpixel_unique'] = wp_generate_uuid4();
	}
	return $data;
}

function perfectpixel_split_lines_add( $key, $product_id, $quantity, $variation_id, $variation, $data ) {
	static $running = false;
	if ( $running || $quantity < 2 || ! perfectpixel_split_lines_applies( $product_id ) ) {
		return;
	}
	$running = true;
	WC()->cart->set_quantity( $key, 1, false );
	for ( $i = 1; $i < $quantity; $i++ ) {
		unset( $data['perfectpixel_unique'] );
		WC()->cart->add_to_cart( $product_id, 1, $variation_id, $variation, $data );
	}
	$running = false;
}
